#!/usr/bin/env node
/**
 * The obliquity beat table — GENERATED by `node tools/verify/obliquity-beat-table.js --write`
 * (plan 31 A2; doc 111 §1.44). The hybrid spin integration's beat band — the mean, min and max of
 * its ε over one obliquity beat of date, the API's 41-sample band instrument — at every 1-Myr node
 * of the engine axis over the navigable domain (2000 + k × 1 Myr, k from kMin to kMax), read by the
 * drawn-scene obliquity rule (earth/scene-obliquity.cjs), the eclipse tier's ground mapping and the
 * Genesis Analysis panel's Obliquity Earth tab in the API, the Node scene and the browser alike.
 *
 * WHY A TABLE: a deep read of the hybrid at a NEW age seats on the nearest bank checkpoint (250 kyr
 * apart off the dense tier) and walks there — 20–30 ms per region at 400 Ma. Read live, the band
 * instrument cost 30 ms per new year (per frame when playing at depth, per besselian evaluation in
 * the genesis finder) and the chart's 480 points 14–23 s; a lazy per-session table still paid one
 * region per point (120 points: 14–23 s). The table makes every node a record.
 *
 * Without --write the script CHECKS: it reads the recorded table and recomputes a spread of its
 * nodes through a fresh model (seated on the spin bank, no table) — FAILS on any difference. With
 * --write it generates every node, then REFUSES unless a second fresh model reproduces a spread of
 * them bit-exactly (visit-order purity) and a model loaded WITH the written table reads the same
 * drawn obliquity as one without it at a spread of years (the record ≡ the instrument).
 */
'use strict';

const fs = require('fs');
const path = require('path');
const { ROOT, buildInputsBlock, modelSourceFiles } = require('../lib/artifact-inputs');
const { createModel } = require('@essrt/physics');
const { NAVIGABLE_PAST_YEARS, NAVIGABLE_FUTURE_YEARS } = require('@essrt/physics/time/navigable-domain');
const { HYBRID_BEAT_TABLE_NODE_YEARS } = require('@essrt/physics/earth/scene-obliquity');

const OUT = path.join(ROOT, 'data', 'obliquity-beat-table.json');
const REL = 'data/obliquity-beat-table.json';
const WRITE = process.argv.includes('--write');

const INPUT_FILES = [
  'tools/verify/obliquity-beat-table.js',
  'packages/physics/src/earth/scene-obliquity.cjs',
  'packages/physics/src/time/navigable-domain.cjs',
  'packages/physics/src/earth/deep-orbital-history.cjs',
  'packages/physics/src/deltat/deep-time-chain.js',
  'packages/physics/src/deltat/deep-time.cjs',
  'packages/physics/src/earth/laplace-plane.cjs',
  'packages/physics/src/deltat/moon-distance-history.cjs',
  'packages/physics/src/deltat/moon-distance-artifact.cjs',
  'packages/physics/src/climate/l1-orbital.cjs',
  'packages/physics/src/constants/generated.js',
  'packages/physics/src/constants/coefficients.js',
  'packages/physics/src/planets/chain-artifact.js',
  'packages/physics/src/moon/deep-modes-artifact.cjs',
  'data/nbody-secular-series.json',
  'data/nbody-deep-secular-modes.json',
  'data/spin-axis-checkpoints.json',
  'public/input/astro-reference.json',
  'public/input/climate-formula-coefficients.json',
  ...modelSourceFiles(),
];

const series = require(path.join(ROOT, 'data', 'nbody-secular-series.json'));
const bank = require(path.join(ROOT, 'data', 'spin-axis-checkpoints.json'));
/** A fresh model seated on the spin bank; with `table` the written artifact beside it. @param {any} [table] */
const freshModel = (table) => createModel(undefined, { secularSeriesArtifact: series, spinCheckpointsArtifact: bank, obliquityBeatTableArtifact: table ?? null });

const kMin = Math.floor(-NAVIGABLE_PAST_YEARS / HYBRID_BEAT_TABLE_NODE_YEARS);
const kMax = Math.ceil(NAVIGABLE_FUTURE_YEARS / HYBRID_BEAT_TABLE_NODE_YEARS);
/** A spread of node indices over the domain, deterministic. */
const SPREAD = [0, -1, -5, -10, -40, -100, -400, -650, -1000, -2460, -3500, -4000, -4400, kMin, 1, 10, 100, 500, 990, kMax].filter((k) => k >= kMin && k <= kMax);
const same3 = (/** @type {number[]} */ a, /** @type {ReadonlyArray<number>} */ b) => a[0] === b[0] && a[1] === b[1] && a[2] === b[2];
const triple = (/** @type {{meanDeg: number, minDeg: number, maxDeg: number}} */ b) => [b.meanDeg, b.minDeg, b.maxDeg];

function main() {
  const t0 = Date.now();
  if (!WRITE) {
    if (!fs.existsSync(OUT)) { console.error(`FAIL — ${REL} is absent. Generate it: node tools/verify/obliquity-beat-table.js --write`); process.exit(1); }
    const art = JSON.parse(fs.readFileSync(OUT, 'utf8'));
    if (art.nodeYears !== HYBRID_BEAT_TABLE_NODE_YEARS || art.kMin !== kMin || art.kMax !== kMax) { console.error(`FAIL — ${REL}'s grid (${art.nodeYears} yr, k ${art.kMin}..${art.kMax}) is not the navigable domain's (${HYBRID_BEAT_TABLE_NODE_YEARS} yr, k ${kMin}..${kMax}). Regenerate: node tools/verify/obliquity-beat-table.js --write`); process.exit(1); }
    const m = freshModel();
    let bad = 0;
    for (const k of SPREAD) {
      const rec = art.nodes[k - art.kMin], live = triple(m.earth.hybridBeatNodeAt(k));
      if (!same3(live, rec)) { bad++; console.error(`  node k ${k} (${(k * HYBRID_BEAT_TABLE_NODE_YEARS / 1e6).toFixed(0)} Myr): recorded ${rec.join(', ')} · live ${live.join(', ')}`); }
    }
    if (bad) { console.error(`FAIL — ${bad} of ${SPREAD.length} spread nodes of ${REL} part from a fresh model. The instrument's inputs moved: regenerate with --write.`); process.exit(1); }
    console.log(`PASS — ${REL}: ${SPREAD.length} spread nodes ≡ a fresh model bit-exactly (k ${art.kMin}..${art.kMax}, ${art.nodes.length} nodes).`);
    return;
  }

  // GENERATE: J2000 outward in each direction (the sampler's walk extends contiguously).
  console.log(`generating the beat table over k ${kMin}..${kMax} (${kMax - kMin + 1} nodes every ${HYBRID_BEAT_TABLE_NODE_YEARS / 1e6} Myr) …`);
  const m = freshModel();
  /** @type {number[][]} */
  const nodes = new Array(kMax - kMin + 1);
  const order = [];
  for (let k = 0; k >= kMin; k--) order.push(k);
  for (let k = 1; k <= kMax; k++) order.push(k);
  let done = 0, tLast = Date.now();
  for (const k of order) {
    nodes[k - kMin] = triple(m.earth.hybridBeatNodeAt(k));
    if (++done % 500 === 0) { console.log(`  ${done} nodes (${(Date.now() - tLast) / 1000} s for the last 500; at k ${k})`); tLast = Date.now(); }
  }
  // gate 1 — a second fresh model reproduces a spread of nodes bit-exactly (visit-order purity)
  const m2 = freshModel();
  const bad1 = SPREAD.filter((k) => !same3(triple(m2.earth.hybridBeatNodeAt(k)), nodes[k - kMin]));
  if (bad1.length) { console.error(`REFUSING: ${bad1.length} spread node(s) differ between two fresh models (visit order): k ${bad1.join(', ')}`); process.exit(1); }
  const art = {
    _description: `The obliquity beat table — GENERATED by tools/verify/obliquity-beat-table.js --write (plan 31 A2, doc 111 §1.44). The hybrid spin integration's beat band — the mean, min and max of its ε over one obliquity beat of date (the API's 41-sample instrument, obliquityBandAt's grid) — at every ${HYBRID_BEAT_TABLE_NODE_YEARS / 1e6}-Myr node of the engine axis over the navigable domain: nodes[k − kMin] = [meanDeg, minDeg, maxDeg] at the year 2000 + k × nodeYears. The drawn-scene obliquity rule (the cited mean of date carrying this band beyond the hybrid's ±10 Myr), the eclipse tier's ground mapping and the Genesis Analysis Obliquity Earth tab read it; a node is a RECORD of the instrument — the generator refuses unless a fresh model reproduces a spread of nodes bit-exactly, and the check mode (no --write) re-reads that spread against the file.`,
    nodeYears: HYBRID_BEAT_TABLE_NODE_YEARS,
    kMin, kMax,
    domainYr: [-NAVIGABLE_PAST_YEARS, NAVIGABLE_FUTURE_YEARS],
    nodes,
    meta: { generatedAtWalkSeconds: Number(((Date.now() - t0) / 1000).toFixed(1)), spreadChecked: SPREAD },
    inputs: buildInputsBlock('node tools/verify/obliquity-beat-table.js --write', INPUT_FILES),
  };
  // gate 2 — a model loaded WITH the table reads the same drawn obliquity and band as one without, at a spread of years (nodes and midpoints)
  const mt = freshModel(art);
  const years = SPREAD.flatMap((k) => [2000 + k * HYBRID_BEAT_TABLE_NODE_YEARS, 2000 + (k + 0.5) * HYBRID_BEAT_TABLE_NODE_YEARS]).filter((y) => y >= 2000 - NAVIGABLE_PAST_YEARS && y <= 2000 + NAVIGABLE_FUTURE_YEARS);
  const bad2 = years.filter((y) => mt.earth.sceneObliquityDeg(y) !== m.earth.sceneObliquityDeg(y) || JSON.stringify(mt.earth.sceneObliquityBandAt(y)) !== JSON.stringify(m.earth.sceneObliquityBandAt(y)));
  if (bad2.length) { console.error(`REFUSING: with the table loaded the drawn obliquity or its band differs from the live instrument at ${bad2.length} year(s): ${bad2.slice(0, 5).join(', ')}`); process.exit(1); }
  fs.writeFileSync(OUT, JSON.stringify(art));
  console.log(`✓ wrote ${REL} — ${nodes.length} nodes, ${(fs.statSync(OUT).size / 1e6).toFixed(2)} MB, ${((Date.now() - t0) / 60000).toFixed(1)} min; ${SPREAD.length} spread nodes reproduced by a second model, ${years.length} years read identically with and without the table`);
}

main();
